/**
 * Todas as cadeias de evolução, para a página de árvores (`/evolucoes`).
 *
 * Gerado da PokéAPI (`/evolution-chain`, 540 cadeias até a espécie #1025) e
 * guardado aqui porque a página precisa de todas de uma vez para filtrar —
 * seriam 540 requests por visita. Cada condição guarda só os campos
 * preenchidos; `expandDetail` em `lib/evolutionTrees` devolve o formato da
 * API. A página é carregada sob demanda, então isto não pesa no resto do site.
 */
export interface EvoDetailLite {
  t: string;
  lv?: number;
  item?: string;
  held?: string;
  move?: string;
  moveType?: string;
  loc?: string;
  hap?: number;
  aff?: number;
  beauty?: number;
  rain?: boolean;
  upside?: boolean;
  gender?: number;
  time?: string;
  tradeFor?: number;
  party?: number;
  partyType?: string;
  stats?: number;
}

export interface EvoChain {
  id: number;
  /** Espécies da cadeia, pai antes dos filhos. */
  species: number[];
  edges: { from: number; to: number; d: EvoDetailLite[] }[];
}

